/* Blue Ridge plant field guide: species data.
   Fields: id, g (group), sci, fam, en, es, st (E endemic, N near endemic, C common, R rare/protected),
   nov (1 = easy to identify in November), code (P = sample only with permission on private land,
   B = buy from farm or nursery, X = never collect), law, el ([low ft, high ft, low open]), fl ([first, last] flowering month),
   tb (NC State Plant Toolbox slug), fws (US Fish and Wildlife page), wk (Wikipedia title), inat (iNaturalist taxon name),
   text fields as [English, Spanish]: now, look, life, hab, where, col, note. */
window.GROUPS = [
  { id: 'con', en: 'Conifers', es: 'Coníferas' },
  { id: 'shr', en: 'Evergreen shrubs', es: 'Arbustos siempreverdes' },
  { id: 'dec', en: 'Trees and shrubs that drop their leaves', es: 'Árboles y arbustos caducifolios' },
  { id: 'gro', en: 'Evergreen ground layer', es: 'Estrato bajo siempreverde' },
  { id: 'wfl', en: 'Wildflowers, dormant now', es: 'Flores silvestres, en reposo ahora' },
  { id: 'mos', en: 'Mosses and lichens', es: 'Musgos y líquenes' },
  { id: 'rar', en: 'Rare: observe only', es: 'Raras: solo observar' }
];

window.SPECIES = [
/* ---------- Conifers ---------- */
{ id:'abies-fraseri', g:'con', sci:'Abies fraseri', fam:'Pinaceae', en:'Fraser fir', es:'Abeto de Fraser', st:'E', nov:1, code:'B',
  law:['IUCN Endangered','En peligro (UICN)'], el:[3900,6684], fl:[5,6], tb:'abies-fraseri',
  now:['Cones have already broken apart, leaving bare upright spikes on the top branches. Look for fallen cone scales, bracts and winged seeds, and for resin blisters on the bark. Christmas tree harvest is underway.',
       'Los conos ya se deshicieron y dejan ejes desnudos y erguidos en las ramas altas. Busquen escamas, brácteas y semillas aladas en el suelo, y ampollas de resina en la corteza. Es temporada de cosecha de árboles de Navidad.'],
  look:['Tree 30 to 55 ft (9 to 17 m), narrow cone shape. Flat, soft needles about 1 in (2.5 cm), dark green above with two silver white bands below, notched tip, strong balsam scent. Young bark smooth and gray with resin blisters. Upright purple cones 1.5 to 2.75 in (3.5 to 7 cm) with yellow green bracts that bend down over the scales.',
        'Árbol de 9 a 17 m, forma cónica estrecha. Agujas planas y suaves de unos 2,5 cm, verde oscuro arriba con dos bandas blanco plateadas abajo, punta con muesca y fuerte olor a bálsamo. Corteza joven lisa y gris con ampollas de resina. Conos erguidos púrpura de 3,5 a 7 cm con brácteas verde amarillentas que se doblan sobre las escamas.'],
  life:['Long lived evergreen tree. Starts producing seed at about 15 years. Pollinates in May and June; cones ripen and fall apart in September and October of the same year, and the wind carries the seeds. Dense carpets of seedlings grow where old trees die.',
        'Árbol perenne de vida larga. Empieza a producir semillas hacia los 15 años. Poliniza en mayo y junio; los conos maduran y se deshacen en septiembre y octubre del mismo año, y el viento lleva las semillas. Donde mueren árboles viejos crecen alfombras densas de plántulas.'],
  hab:['Spruce and fir forest on the highest peaks, in fog, wind and cold. Thin, rocky, cool, moist soils (Spodosols and Inceptisols) with a thick organic layer; strongly acidic, often near pH 4 or lower.',
       'Bosque de abetos y píceas en las cumbres más altas, con niebla, viento y frío. Suelos delgados, rocosos, fríos y húmedos (Espodosoles e Inceptisoles) con una capa orgánica gruesa; muy ácidos, a menudo cerca de pH 4 o menos.'],
  where:['Mount Mitchell summit trails; Grandfather Mountain ridges; Christmas tree farms around Boone. Off route: Black Balsam Knob, Roan Mountain.',
         'Senderos de la cumbre del Monte Mitchell; crestas de Grandfather Mountain; fincas de árboles de Navidad cerca de Boone. Fuera de ruta: Black Balsam Knob, Roan Mountain.'],
  col:['Photo only in the parks. Legal sample: buy boughs or a small tree at a Christmas tree farm.',
       'Solo foto en los parques. Muestra legal: compren ramas o un árbol pequeño en una finca de árboles de Navidad.'],
  note:['The balsam woolly adelgid, an insect from Europe, killed more than 80 percent of mature trees in the 20th century; the gray dead trunks on Mount Mitchell are its mark. Warming climate squeezes its cold habitat further. North Carolina\'s official Christmas tree.',
        'El adelgido lanudo del bálsamo, un insecto europeo, mató más del 80 por ciento de los árboles maduros en el siglo XX; los troncos grises muertos del Monte Mitchell son su huella. El calentamiento reduce aún más su hábitat frío. Es el árbol de Navidad oficial de Carolina del Norte.'] },

{ id:'picea-rubens', g:'con', sci:'Picea rubens', fam:'Pinaceae', en:'Red spruce', es:'Pícea roja', st:'C', nov:1, code:'P',
  el:[4500,6684], fl:[5,6], tb:'picea-rubens',
  now:['Ripe cones have shed their seeds. Fallen cones lie whole under the trees, an easy sign of spruce.',
       'Los conos maduros ya soltaron sus semillas. Los conos caídos quedan enteros bajo los árboles, una señal fácil de pícea.'],
  look:['Tree 70 to 100 ft (21 to 30 m), narrow crown. Stiff, sharp, four sided needles 0.5 to 0.6 in (1.2 to 1.5 cm) that roll between your fingers, each on a tiny woody peg. Hanging reddish brown cones 1.2 to 2 in (3 to 5 cm). Flaky gray brown bark, reddish beneath.',
        'Árbol de 21 a 30 m, copa estrecha. Agujas rígidas, punzantes, de cuatro lados, de 1,2 a 1,5 cm, que ruedan entre los dedos, cada una sobre una clavija leñosa. Conos colgantes marrón rojizo de 3 a 5 cm. Corteza escamosa gris marrón, rojiza debajo.'],
  life:['Slow growing and shade tolerant; can live about 400 years. Pollinates in May and June; cones ripen in fall and drop whole.',
        'Crecimiento lento, tolera la sombra; puede vivir unos 400 años. Poliniza en mayo y junio; los conos maduran en otoño y caen enteros.'],
  hab:['Cool, foggy slopes and summits, with Fraser fir above and yellow birch below. Shallow, rocky, very acidic soils.',
       'Laderas y cumbres frías y nubladas, con abeto de Fraser arriba y abedul amarillo abajo. Suelos poco profundos, rocosos y muy ácidos.'],
  where:['Mount Mitchell; Grandfather Mountain; scattered trees near Craggy Gardens.',
         'Monte Mitchell; Grandfather Mountain; árboles dispersos cerca de Craggy Gardens.'],
  col:['Photo only on your route. With permission on private high elevation land, a fallen cone is the easiest sample.',
       'Solo foto en su ruta. Con permiso en terreno privado alto, un cono caído es la muestra más fácil.'] },

{ id:'tsuga-caroliniana', g:'con', sci:'Tsuga caroliniana', fam:'Pinaceae', en:'Carolina hemlock', es:'Tsuga de Carolina', st:'E', nov:1, code:'X',
  law:['Becoming rare','Cada vez más rara'], el:[2000,4000], fl:[4,5], tb:'tsuga-caroliniana',
  now:['Opened brown cones stay on the tree into winter. Check needle bases for white cottony tufts: that is the hemlock woolly adelgid.',
       'Los conos marrones abiertos permanecen en el árbol durante el invierno. Revisen la base de las agujas en busca de motas blancas algodonosas: es el adelgido lanudo de la tsuga.'],
  look:['Tree 30 to 70 ft (9 to 21 m), often leaning from cliffs. Needles 0.25 to 0.75 in (0.6 to 2 cm) stand out all around the twig like a bottle brush, with two white stripes below. Crushed foliage smells of tangerine. Cones 1 to 1.5 in (2.5 to 3.8 cm), scales opening wide.',
        'Árbol de 9 a 21 m, a menudo inclinado desde los riscos. Agujas de 0,6 a 2 cm alrededor de toda la ramita como un cepillo, con dos rayas blancas abajo. El follaje aplastado huele a mandarina. Conos de 2,5 a 3,8 cm, con escamas muy abiertas.'],
  life:['Slow growing and long lived. Seedlings can wait decades in shade until a gap opens. Pollen in April and May; cones mature in the first autumn.',
        'Crecimiento lento y vida larga. Las plántulas pueden esperar décadas en la sombra hasta que se abre un claro. Polen en abril y mayo; los conos maduran el primer otoño.'],
  hab:['Dry rocky bluffs, cliff edges and ridges, often with mountain laurel and pines. Thin, acidic, well drained soils over rock.',
       'Riscos rocosos secos, bordes de acantilados y crestas, a menudo con laurel de montaña y pinos. Suelos delgados, ácidos y bien drenados sobre roca.'],
  where:['Rocky rim of Linville Gorge on the Linville Falls Trail to Erwins View. Off route: Table Rock and Hawksbill in Linville Gorge.',
         'Borde rocoso de la garganta de Linville en el sendero a Erwins View. Fuera de ruta: Table Rock y Hawksbill en Linville Gorge.'],
  col:['Photo only. Never move hemlock twigs between sites: they can carry the adelgid. Some nurseries sell treated trees.',
       'Solo foto. Nunca muevan ramitas de tsuga entre sitios: pueden llevar el adelgido. Algunos viveros venden árboles tratados.'],
  note:['The hemlock woolly adelgid, an insect from Asia, kills trees in about 4 to 15 years. Predatory beetles (Laricobius nigrinus, Sasajiscymnus tsugae) are released as biological control where trees on cliffs cannot be treated. Look alike: eastern hemlock has needles in two flat rows and smaller cones.',
        'El adelgido lanudo de la tsuga, un insecto asiático, mata los árboles en unos 4 a 15 años. Se liberan escarabajos depredadores (Laricobius nigrinus, Sasajiscymnus tsugae) como control biológico donde no se pueden tratar los árboles de los riscos. Parecida: la tsuga del este tiene agujas en dos filas planas y conos más pequeños.'] },

{ id:'tsuga-canadensis', g:'con', sci:'Tsuga canadensis', fam:'Pinaceae', en:'Eastern hemlock', es:'Tsuga del este', st:'C', nov:1, code:'X',
  law:['Declining','En declive'], el:[1000,5000,1], fl:[4,5], tb:'tsuga-canadensis',
  now:['Evergreen and easy to spot along streams. Small open cones hang at the twig tips. Check for adelgid tufts under the needles.',
       'Siempreverde y fácil de ver junto a los arroyos. Conos pequeños y abiertos cuelgan en las puntas. Revisen si hay motas del adelgido bajo las agujas.'],
  look:['Large tree, to 100 ft (30 m) or more, with a drooping top. Flat needles 0.4 to 0.6 in (1 to 1.5 cm) in two flat rows, two white lines below, on tiny stalks. Cones only 0.6 to 0.8 in (1.5 to 2 cm).',
        'Árbol grande, de hasta 30 m o más, con la punta caída. Agujas planas de 1 a 1,5 cm en dos filas, con dos líneas blancas abajo, sobre pecíolos diminutos. Conos de solo 1,5 a 2 cm.'],
  life:['Very long lived; old trees reach 300 to 500 years. Pollen in April and May; cones ripen September and October.',
        'Vida muy larga; los árboles viejos alcanzan 300 a 500 años. Polen en abril y mayo; los conos maduran en septiembre y octubre.'],
  hab:['Cool, shady stream valleys and north slopes. Moist, acidic, well drained soil. Its shade keeps headwater streams cold for native brook trout.',
       'Valles sombreados junto a arroyos y laderas norte. Suelo húmedo, ácido y bien drenado. Su sombra mantiene frías las cabeceras para la trucha de arroyo nativa.'],
  where:['Linville Falls, Price Lake, Moses Cone, Bent Creek.', 'Linville Falls, Price Lake, Moses Cone, Bent Creek.'],
  col:['Photo only. Do not move twigs between sites.', 'Solo foto. No muevan ramitas entre sitios.'],
  note:['Hemlock woolly adelgid kills untreated trees in about 4 to 10 years; many trees along trails are now treated.',
        'El adelgido mata los árboles no tratados en unos 4 a 10 años; muchos árboles junto a los senderos ya están tratados.'] },

/* ---------- Evergreen shrubs ---------- */
{ id:'rhododendron-catawbiense', g:'shr', sci:'Rhododendron catawbiense', fam:'Ericaceae', en:'Catawba rhododendron', es:'Rododendro de Catawba', st:'N', nov:1, code:'B',
  el:[3000,6684], fl:[5,6], tb:'rhododendron-catawbiense',
  now:['Fat, scaly flower buds sit at the branch tips (thin buds are leaf buds). Dry brown capsules split into five parts and release dust fine seeds. On cold mornings the leaves curl into tubes and droop.',
       'Yemas florales gruesas y escamosas en las puntas (las delgadas son yemas de hoja). Cápsulas secas marrones que se abren en cinco partes y sueltan semillas finas como polvo. En mañanas frías las hojas se enrollan como tubos y cuelgan.'],
  look:['Shrub 6 to 10 ft (2 to 3 m) forming dense thickets. Thick, glossy leaves 3 to 6 in (8 to 15 cm), rounded at both ends, pale and smooth below. Lavender pink flowers in round clusters of 15 to 20.',
        'Arbusto de 2 a 3 m que forma matorrales densos. Hojas gruesas y brillantes de 8 a 15 cm, redondeadas en ambos extremos, pálidas y lisas por debajo. Flores rosa lavanda en ramilletes redondos de 15 a 20.'],
  life:['Long lived woody shrub. Blooms late May and June, peaking around mid June at Craggy Gardens. Capsules ripen in fall; next year\'s buds form in late summer.',
        'Arbusto leñoso de vida larga. Florece a fines de mayo y en junio, con su máximo hacia mediados de junio en Craggy Gardens. Las cápsulas maduran en otoño; las yemas del año siguiente se forman a fines del verano.'],
  hab:['High heath balds, rocky summits and ridge forests. Shallow, organic, acidic soils (about pH 4.5 to 5.5) that stay moist but drain well. A few low populations in the Piedmont.',
       'Brezales de altura, cumbres rocosas y bosques de cresta. Suelos poco profundos, orgánicos y ácidos (pH 4,5 a 5,5 aprox.), húmedos pero bien drenados. Algunas poblaciones bajas en el Piedmont.'],
  where:['Craggy Gardens and Craggy Pinnacle (the "gardens" are this shrub), Rough Ridge, Grandfather Mountain. Off route: Roan Mountain rhododendron gardens.',
         'Craggy Gardens y Craggy Pinnacle (los "jardines" son este arbusto), Rough Ridge, Grandfather Mountain. Fuera de ruta: jardines de rododendro de Roan Mountain.'],
  col:['Photo only on your route. Buy the straight species, not a hybrid, at a native plant nursery.',
       'Solo foto en su ruta. Compren la especie pura, no un híbrido, en un vivero de plantas nativas.'],
  note:['Phytophthora cinnamomi, an introduced soil water mold, causes root rot in rhododendrons; clean boots between sites. Look alike: great rhododendron has longer leaves with a tapered base and blooms later.',
        'Phytophthora cinnamomi, un oomiceto introducido del suelo, pudre las raíces de los rododendros; limpien las botas entre sitios. Parecida: el rododendro grande tiene hojas más largas, de base angosta, y florece más tarde.'] },

{ id:'rhododendron-maximum', g:'shr', sci:'Rhododendron maximum', fam:'Ericaceae', en:'Great (rosebay) rhododendron', es:'Rododendro grande', st:'C', nov:1, code:'PB',
  el:[1000,5500,1], fl:[6,7], tb:'rhododendron-maximum',
  now:['Sticky oblong capsules from this summer are splitting open. Leaves roll into tight tubes below about 20 °F (minus 7 °C): a natural thermometer.',
       'Las cápsulas oblongas y pegajosas de este verano se están abriendo. Las hojas se enrollan en tubos apretados bajo unos 7 °C bajo cero: un termómetro natural.'],
  look:['Large shrub or small tree 10 to 20 ft (3 to 6 m) with twisting trunks. Leathery leaves 4 to 8 in (10 to 20 cm), sometimes longer, with a tapered base and pointed tip, and fine rusty or whitish hairs below. Summer flowers white to pale pink with green or orange spots.',
        'Arbusto grande o árbol pequeño de 3 a 6 m con troncos retorcidos. Hojas coriáceas de 10 a 20 cm, a veces más, de base angosta y punta aguda, con pelos finos rojizos o blanquecinos por debajo. Flores de verano blancas a rosa pálido con manchas verdes o naranja.'],
  life:['Long lived; spreads by layering, when low branches root where they touch the ground. Blooms late June and July, after Catawba rhododendron. Capsules ripen September and October.',
        'Vida larga; se extiende por acodo, cuando ramas bajas enraízan al tocar el suelo. Florece a fines de junio y en julio, después del rododendro de Catawba. Las cápsulas maduran en septiembre y octubre.'],
  hab:['Shady stream banks, coves and north slopes, often under hemlock. Moist, very acidic, organic soils; no heavy clay.',
       'Orillas sombreadas de arroyos, hondonadas y laderas norte, a menudo bajo tsugas. Suelos húmedos, muy ácidos y orgánicos; no tolera arcilla pesada.'],
  where:['Price Lake and Boone Fork, Linville Falls, Moses Cone, lower trails at Craggy Gardens, almost every stream.',
         'Price Lake y Boone Fork, Linville Falls, Moses Cone, senderos bajos de Craggy Gardens, casi cualquier arroyo.'],
  col:['Photo only on your route. With permission on private land, where it is very common. Nurseries sell it.',
       'Solo foto en su ruta. Con permiso en terreno privado, donde es muy común. Se vende en viveros.'],
  note:['Its dense thickets, called "laurel hells", shade the forest floor, and its slow decaying, tannin rich leaf litter ties up soil nitrogen. Together these suppress tree seedlings such as red maple and red oak.',
        'Sus matorrales densos, llamados "laurel hells", sombrean el suelo, y su hojarasca rica en taninos y lenta para descomponerse inmoviliza el nitrógeno del suelo. Juntos suprimen plántulas de árboles como el arce rojo y el roble rojo.'] },

{ id:'kalmia-latifolia', g:'shr', sci:'Kalmia latifolia', fam:'Ericaceae', en:'Mountain laurel', es:'Laurel de montaña', st:'C', nov:1, code:'PB',
  el:[1000,6000,1], fl:[5,6], tb:'kalmia-latifolia',
  now:['Small round brown capsules, about 0.2 in (5 mm), each topped by a thin persistent style. Pink, knobby flower bud clusters for next spring.',
       'Cápsulas redondas y marrones de unos 5 mm, cada una con un estilo delgado persistente. Racimos de yemas florales rosadas y nudosas para la próxima primavera.'],
  look:['Shrub 6 to 10 ft (2 to 3 m) with crooked stems. Glossy leaves 2 to 5 in (5 to 13 cm), pointed at both ends, yellow green and smooth below. Cup shaped white to pink flowers hold their ten anthers in pockets; when a bee lands, the stamens spring up and fling pollen.',
        'Arbusto de 2 a 3 m de tallos torcidos. Hojas brillantes de 5 a 13 cm, agudas en ambos extremos, verde amarillento y lisas por debajo. Las flores en copa, blancas a rosadas, guardan sus diez anteras en bolsillos; cuando se posa una abeja, los estambres saltan y lanzan el polen.'],
  life:['Slow growing, long lived. Blooms from late April to July depending on elevation; capsules ripen September and October and persist into winter.',
        'Crecimiento lento y vida larga. Florece de fines de abril a julio según la altitud; las cápsulas maduran en septiembre y octubre y persisten en invierno.'],
  hab:['Dry rocky ridges, outcrops, balds and acidic oak and pine forests. Well drained, acidic, humus rich, sandy or rocky soils; no wet clay.',
       'Crestas rocosas secas, afloramientos, brezales y bosques ácidos de robles y pinos. Suelos bien drenados, ácidos, ricos en humus, arenosos o rocosos; no tolera arcilla húmeda.'],
  where:['Rough Ridge, Beacon Heights, Linville Falls, Moses Cone, Craggy Gardens.', 'Rough Ridge, Beacon Heights, Linville Falls, Moses Cone, Craggy Gardens.'],
  col:['Photo only on your route. With permission on private land. Nurseries sell it.', 'Solo foto en su ruta. Con permiso en terreno privado. Se vende en viveros.'],
  note:['Poisonous; not a culinary laurel. Mountain residents often call rhododendron "laurel" and this plant "ivy".',
        'Venenosa; no es un laurel de cocina. En la montaña suelen llamar "laurel" al rododendro e "ivy" a esta planta.'] },

{ id:'pieris-floribunda', g:'shr', sci:'Pieris floribunda', fam:'Ericaceae', en:'Mountain fetterbush', es:'Pieris de montaña', st:'E', nov:1, code:'B',
  law:['NC Watch List','Lista de vigilancia de NC'], el:[4000,6000], fl:[5,6], tb:'pieris-floribunda',
  now:['Its best season for identification: upright sprays of white, bead like flower buds stand above the leaves all winter. The garden pieris from Japan holds its bud clusters drooping instead.',
       'Su mejor temporada para identificarla: ramilletes erguidos de yemas florales blancas como cuentas se alzan sobre las hojas todo el invierno. La pieris japonesa de jardín tiene los racimos colgantes.'],
  look:['Compact shrub 3 to 6 ft (1 to 2 m). Leathery leaves 1 to 3 in (2.5 to 7.5 cm) with tiny bristly hairs along the edges (use a hand lens). Upright clusters of small white bells in spring.',
        'Arbusto compacto de 1 a 2 m. Hojas coriáceas de 2,5 a 7,5 cm con diminutos pelos rígidos en el borde (usen lupa). Racimos erguidos de campanitas blancas en primavera.'],
  life:['Flower buds form in autumn and open in May and June; brown capsules ripen August to October and can persist a year.',
        'Las yemas se forman en otoño y abren en mayo y junio; las cápsulas maduran de agosto a octubre y pueden durar un año.'],
  hab:['High heath balds, acidic wooded slopes and rocky summits, in sun. Dry to moist, acidic, well drained soils.',
       'Brezales de altura, laderas boscosas ácidas y cumbres rocosas, al sol. Suelos secos a húmedos, ácidos y bien drenados.'],
  where:['Uncommon on your route; search high heath balds. Abundant along the Parkway south of Graveyard Fields (MP 419 and beyond), southwest of Asheville.',
         'Poco común en su ruta; búsquenla en brezales altos. Abundante en la Parkway al sur de Graveyard Fields (MP 419 en adelante), al suroeste de Asheville.'],
  col:['Photo only in the wild. Some native nurseries sell it.', 'Solo foto en estado silvestre. Algunos viveros nativos la venden.'] },

{ id:'leucothoe-fontanesiana', g:'shr', sci:'Leucothoe fontanesiana', fam:'Ericaceae', en:'Mountain doghobble', es:'Doghobble de montaña', st:'N', nov:1, code:'PB',
  el:[1500,5000], fl:[4,5], tb:'leucothoe-fontanesiana',
  now:['Leaves turn red to burgundy in sun and cold. Short spikes of next year\'s flower buds sit in the leaf angles.',
       'Las hojas se tornan rojas a burdeos con sol y frío. Espigas cortas de yemas florales del año siguiente en las axilas de las hojas.'],
  look:['Arching shrub 3 to 6 ft (1 to 2 m) that forms tangled colonies. Glossy, lance shaped leaves 2 to 6 in (5 to 15 cm) with long tips and fine teeth, in two rows along zigzag stems.',
        'Arbusto arqueado de 1 a 2 m que forma colonias enmarañadas. Hojas brillantes, lanceoladas, de 5 a 15 cm, de punta larga y dientes finos, en dos filas a lo largo de tallos en zigzag.'],
  life:['Long lived; spreads by root suckers. Hanging chains of white urn shaped flowers April to June; small five lobed capsules September and October.',
        'Vida larga; se extiende por brotes de raíz. Cadenas colgantes de flores blancas en forma de urna de abril a junio; cápsulas pequeñas de cinco lóbulos en septiembre y octubre.'],
  hab:['Wet ravines and stream banks, often under great rhododendron and hemlock. Moist to wet, acidic soils; dislikes drought and wind.',
       'Barrancos húmedos y orillas de arroyos, a menudo bajo rododendro grande y tsuga. Suelos húmedos a mojados y ácidos; no tolera sequía ni viento.'],
  where:['Boone Fork and Price Lake, Linville Falls, Bent Creek, any shaded stream crossing.', 'Boone Fork y Price Lake, Linville Falls, Bent Creek, cualquier cruce de arroyo sombreado.'],
  col:['Photo only on your route. With permission on private land. Widely sold by nurseries.', 'Solo foto en su ruta. Con permiso en terreno privado. Se vende mucho en viveros.'],
  note:['Named for bear hunts: bears pushed through tangles that "hobbled" the dogs. Leaves and flowers are highly toxic if eaten.',
        'El nombre viene de la caza de osos: los osos atravesaban matorrales que "trababan" a los perros. Hojas y flores son muy tóxicas si se ingieren.'] },

/* ---------- Deciduous trees and shrubs ---------- */
{ id:'hamamelis-virginiana', g:'dec', sci:'Hamamelis virginiana', fam:'Hamamelidaceae', en:'American witch hazel', es:'Hamamelis de Virginia', st:'C', nov:1, code:'PB',
  el:[1000,5000,1], fl:[10,12], tb:'hamamelis-virginiana',
  now:['In flower now, the only native tree that blooms in November. Yellow flowers with four thin, crinkled ribbon petals line the bare twigs. On the same branches, last year\'s woody capsules split and shoot two black seeds up to about 30 ft (9 m).',
       'En flor ahora, el único árbol nativo que florece en noviembre. Flores amarillas con cuatro pétalos delgados y arrugados como cintas a lo largo de ramas desnudas. En las mismas ramas, las cápsulas leñosas del año anterior se abren y disparan dos semillas negras hasta unos 9 m.'],
  look:['Large shrub or small tree 15 to 30 ft (4.5 to 9 m) with several smooth gray trunks. Lopsided leaves with wavy, scalloped edges and an uneven base.',
        'Arbusto grande o árbol pequeño de 4,5 a 9 m con varios troncos grises y lisos. Hojas asimétricas de borde ondulado y festoneado, con base desigual.'],
  life:['Blooms October to December. Flowers pollinated in fall become fruit over the next year, so flowers and ripe fruit appear together.',
        'Florece de octubre a diciembre. Las flores polinizadas en otoño forman el fruto durante el año siguiente, así que flores y frutos maduros aparecen juntos.'],
  hab:['Forest edges, understory, stream banks and slopes. Moist, acidic to near neutral, well drained soils; low and middle elevations.',
       'Bordes de bosque, sotobosque, orillas de arroyos y laderas. Suelos húmedos, ácidos a casi neutros, bien drenados; altitudes bajas y medias.'],
  where:['NC Arboretum and Bent Creek, Moses Cone carriage roads, Price Park, Linville Falls.', 'Arboreto y Bent Creek, caminos de Moses Cone, Price Park, Linville Falls.'],
  col:['Photo only on public land. With permission, a flowering twig on private land. Nurseries sell it.', 'Solo foto en tierra pública. Con permiso, una ramita en flor en terreno privado. Se vende en viveros.'],
  note:['Its bark extract is the "witch hazel" sold in pharmacies.', 'El extracto de su corteza es el "hamamelis" que se vende en farmacias.'] },

{ id:'sorbus-americana', g:'dec', sci:'Sorbus americana', fam:'Rosaceae', en:'American mountain ash', es:'Serbal americano', st:'C', nov:1, code:'X',
  el:[4500,6684], fl:[5,6], tb:'sorbus-americana',
  now:['Fruit clusters may remain if birds left them. Sticky, dark red, hairy buds on stout twigs.',
       'Pueden quedar racimos de frutos si las aves los dejaron. Yemas rojo oscuro, pegajosas y vellosas sobre ramitas gruesas.'],
  look:['Small tree 15 to 30 ft (4.5 to 9 m). Compound leaves with 9 to 17 narrow, toothed leaflets. Clusters of red orange fruits about 0.25 in (6 mm), like tiny apples. Not a true ash: it belongs to the rose family.',
        'Árbol pequeño de 4,5 a 9 m. Hojas compuestas con 9 a 17 folíolos estrechos y dentados. Racimos de frutos rojo anaranjados de unos 6 mm, como manzanas diminutas. No es un fresno: pertenece a la familia de las rosas.'],
  life:['Short lived tree. Flat white flower clusters in late spring and early summer; fruit ripens September and October; birds spread the seeds.',
        'Árbol de vida corta. Racimos planos de flores blancas a fines de primavera y principios de verano; el fruto madura en septiembre y octubre; las aves dispersan las semillas.'],
  hab:['Spruce and fir forest edges, rock outcrops and high balds. Moist, rocky, acidic soils.', 'Bordes del bosque de abetos y píceas, afloramientos y brezales altos. Suelos húmedos, rocosos y ácidos.'],
  where:['Craggy Gardens and Craggy Pinnacle, Mount Mitchell. Off route: Graveyard Fields, Black Balsam.', 'Craggy Gardens y Craggy Pinnacle, Monte Mitchell. Fuera de ruta: Graveyard Fields, Black Balsam.'],
  col:['Photo only. The fruit is not on the Parkway\'s list of berries you may gather.', 'Solo foto. El fruto no está en la lista de bayas que se pueden recoger en la Parkway.'] },

{ id:'betula-alleghaniensis', g:'dec', sci:'Betula alleghaniensis', fam:'Betulaceae', en:'Yellow birch', es:'Abedul amarillo', st:'C', nov:1, code:'P',
  el:[3000,6000], fl:[4,5], tb:'betula-alleghaniensis',
  now:['Bare branches carry next spring\'s male catkins. Female catkins shatter into tiny winged seeds and three lobed scales.',
       'Las ramas desnudas llevan los amentos masculinos de la próxima primavera. Los amentos femeninos se deshacen en semillas aladas diminutas y escamas de tres lóbulos.'],
  look:['Tree 70 to 80 ft (21 to 24 m), the largest North American birch. Shiny bronze or silver yellow bark peeling in thin, curly strips. Scratch a twig: it smells of wintergreen. Trees that sprouted on rotting logs stand on arching "stilt" roots.',
        'Árbol de 21 a 24 m, el abedul más grande de Norteamérica. Corteza bronce o amarillo plateado brillante que se pela en tiras delgadas y rizadas. Raspen una ramita: huele a gaulteria. Los árboles que brotaron sobre troncos podridos se alzan sobre raíces arqueadas como zancos.'],
  life:['Long lived; wind pollinated in spring. Seeds ripen in late summer and fall and germinate best on mossy logs.',
        'Vida larga; polinizado por el viento en primavera. Las semillas maduran a fines del verano y en otoño y germinan mejor sobre troncos con musgo.'],
  hab:['Northern hardwood forests, coves and boulder fields. Moist, acidic, rocky loams; usually above about 3,000 ft.', 'Bosques de frondosas norteñas, hondonadas y campos de rocas. Suelos francos húmedos, ácidos y rocosos; por lo general sobre unos 900 m.'],
  where:['Craggy Gardens, Boone Fork, Mount Mitchell, Grandfather Mountain.', 'Craggy Gardens, Boone Fork, Monte Mitchell, Grandfather Mountain.'],
  col:['Photo only on public land. Never peel bark from a living tree. With permission, shed bark and catkins from the ground.', 'Solo foto en tierra pública. Nunca pelen la corteza de un árbol vivo. Con permiso, corteza desprendida y amentos del suelo.'] },

{ id:'fagus-grandifolia', g:'dec', sci:'Fagus grandifolia', fam:'Fagaceae', en:'American beech', es:'Haya americana', st:'C', nov:1, code:'P',
  el:[1000,5500,1], fl:[4,5], tb:'fagus-grandifolia',
  now:['Young trees keep pale tan, papery dead leaves all winter (marcescence), the quickest way to spot beech in a bare forest. Spiny husks and three sided nuts on the ground.',
       'Los árboles jóvenes conservan todo el invierno hojas muertas color canela pálido (marcescencia), la forma más rápida de reconocer el haya en un bosque desnudo. Cúpulas espinosas y nueces de tres lados en el suelo.'],
  look:['Tree 60 to 80 ft (18 to 24 m) in valleys, short and twisted in windy high gaps. Smooth, light gray bark that stays smooth with age. Long, slender, pointed buds like cigars, 0.75 to 1 in (2 to 2.5 cm).',
        'Árbol de 18 a 24 m en los valles, bajo y retorcido en los collados ventosos. Corteza gris clara y lisa, que sigue lisa con la edad. Yemas largas, delgadas y puntiagudas como cigarros, de 2 a 2,5 cm.'],
  life:['Long lived and shade tolerant. Flowers April and May; nuts ripen September and October. Root sprouts form clonal groves.',
        'Vida larga, tolera la sombra. Florece en abril y mayo; las nueces maduran en septiembre y octubre. Los brotes de raíz forman bosquetes clonales.'],
  hab:['Coves, slopes and "beech gaps", high windy saddles where dwarf beech forms its own forest. Moist, acidic, well drained soils.',
       'Hondonadas, laderas y "beech gaps", collados altos y ventosos donde hayas enanas forman su propio bosque. Suelos húmedos, ácidos y bien drenados.'],
  where:['Craggy Gardens Trail, Moses Cone, NC Arboretum.', 'Sendero de Craggy Gardens, Moses Cone, Arboreto.'],
  col:['Photo only on public land. With permission, marcescent leaves and husks on private land.', 'Solo foto en tierra pública. Con permiso, hojas marcescentes y cúpulas en terreno privado.'],
  note:['Beech bark disease, started by a scale insect from Europe, has damaged many high elevation beech stands.', 'La enfermedad de la corteza del haya, iniciada por una cochinilla europea, ha dañado muchos rodales de haya de altura.'] },

{ id:'oxydendrum-arboreum', g:'dec', sci:'Oxydendrum arboreum', fam:'Ericaceae', en:'Sourwood', es:'Sourwood, árbol agrio', st:'C', nov:1, code:'PB',
  el:[1000,4500,1], fl:[6,8], tb:'oxydendrum-arboreum',
  now:['Drooping, one sided sprays of small silver gray capsules hang on bare branches all winter. A few crimson leaves may remain at lower elevations.',
       'Ramilletes colgantes de cápsulas pequeñas gris plateado cuelgan de un lado en ramas desnudas todo el invierno. A baja altura pueden quedar algunas hojas carmesí.'],
  look:['Slender tree 25 to 50 ft (8 to 15 m), often leaning, with deeply furrowed gray bark and bright red young shoots. Glossy, finely toothed leaves that taste sour.',
        'Árbol delgado de 8 a 15 m, a menudo inclinado, con corteza gris de surcos profundos y brotes jóvenes rojo brillante. Hojas brillantes, finamente dentadas, de sabor agrio.'],
  life:['Fragrant white bell flowers in long sprays, late June to August; bees make the prized Appalachian sourwood honey. Capsules ripen September to November.',
        'Flores blancas fragantes en campana, en ramilletes largos, de fines de junio a agosto; las abejas producen la apreciada miel de sourwood. Las cápsulas maduran de septiembre a noviembre.'],
  hab:['Dry to moist oak forests, ridges and edges. Acidic, well drained, often rocky soils.', 'Bosques de robles secos a húmedos, crestas y bordes. Suelos ácidos, bien drenados, a menudo rocosos.'],
  where:['NC Arboretum and Bent Creek, lower Parkway near Asheville, Linville Falls.', 'Arboreto y Bent Creek, Parkway baja cerca de Asheville, Linville Falls.'],
  col:['Photo only on public land. With permission, a capsule spray on private land. Buy local sourwood honey.', 'Solo foto en tierra pública. Con permiso, un ramillete de cápsulas en terreno privado. Compren miel local de sourwood.'] },

{ id:'clethra-acuminata', g:'dec', sci:'Clethra acuminata', fam:'Clethraceae', en:'Mountain sweet pepperbush', es:'Clethra de montaña', st:'N', nov:1, code:'PB',
  el:[1500,5500], fl:[6,8], tb:'clethra-acuminata',
  now:['Bare stems glow with smooth, cinnamon colored bark. Drooping chains of round, peppercorn like capsules.', 'Tallos desnudos con corteza lisa color canela. Cadenas colgantes de cápsulas redondas como granos de pimienta.'],
  look:['Shrub or small tree 8 to 15 ft (2.5 to 4.5 m). Outer bark peels away to show the cinnamon inner bark. Leaves 3 to 6 in (8 to 15 cm), toothed, with long pointed tips and hairy undersides.',
        'Arbusto o árbol pequeño de 2,5 a 4,5 m. La corteza externa se desprende y muestra la interna color canela. Hojas de 8 a 15 cm, dentadas, de punta larga y envés velloso.'],
  life:['Fragrant white flowers in drooping spikes, June to August; capsules ripen September and October.', 'Flores blancas fragantes en espigas colgantes de junio a agosto; cápsulas en septiembre y octubre.'],
  hab:['Cove forests, stream sides and rocky slopes, often with rhododendron. Moist, humus rich, acidic, rocky soils.', 'Bosques de hondonada, orillas de arroyos y laderas rocosas, a menudo con rododendro. Suelos húmedos, ricos en humus, ácidos y rocosos.'],
  where:['Craggy Gardens, Boone Fork, Linville Falls, Moses Cone.', 'Craggy Gardens, Boone Fork, Linville Falls, Moses Cone.'],
  col:['Photo only on public land. With permission, a capsule chain or shed bark. Native nurseries sell it.', 'Solo foto en tierra pública. Con permiso, una cadena de cápsulas o corteza desprendida. Se vende en viveros nativos.'] },

{ id:'viburnum-lantanoides', g:'dec', sci:'Viburnum lantanoides', fam:'Viburnaceae', en:'Hobblebush', es:'Viburno de montaña', st:'C', nov:1, code:'X',
  el:[4000,6684], fl:[5,6], tb:'viburnum-lantanoides',
  now:['Naked buds with no scales, covered in tan, felty hairs: tiny folded leaves and round flower buds. Excellent macro subjects.', 'Yemas desnudas, sin escamas, cubiertas de pelos afieltrados color canela: hojitas plegadas y yemas florales redondas. Excelentes para macrofotografía.'],
  look:['Sprawling shrub 6 to 10 ft (2 to 3 m). Large, round, heart shaped leaves 4 to 8 in (10 to 20 cm) in opposite pairs. Arching branches root where they touch the ground and trip walkers, hence "hobble".',
        'Arbusto extendido de 2 a 3 m. Hojas grandes, redondas y acorazonadas de 10 a 20 cm en pares opuestos. Las ramas arqueadas enraízan al tocar el suelo y hacen tropezar, de ahí "hobble".'],
  life:['Spreads by layering. Flat white flower clusters in May and June, ringed by large sterile flowers that attract insects; fruit turns red, then purple black, in late summer.',
        'Se extiende por acodo. Racimos planos de flores blancas en mayo y junio, rodeados de flores grandes estériles que atraen insectos; el fruto pasa de rojo a negro morado a fines del verano.'],
  hab:['Spruce and fir forest and northern hardwoods, on moist, shady slopes. Acidic to neutral, gravelly or rocky loams.', 'Bosque de abetos y píceas y frondosas norteñas, en laderas húmedas y sombreadas. Suelos francos ácidos a neutros, con grava o rocas.'],
  where:['Mount Mitchell, Craggy Gardens, Grandfather Mountain.', 'Monte Mitchell, Craggy Gardens, Grandfather Mountain.'],
  col:['Photo only on your route.', 'Solo foto en su ruta.'] },

{ id:'magnolia-fraseri', g:'dec', sci:'Magnolia fraseri', fam:'Magnoliaceae', en:'Fraser magnolia', es:'Magnolia de Fraser', st:'E', nov:1, code:'P',
  el:[2000,5000], fl:[4,5], tb:'magnolia-fraseri',
  now:['Look on the ground for giant fallen leaves with two small "ears" at the base, and on the twig tips for a large purple brown bud.', 'Busquen en el suelo hojas gigantes caídas con dos pequeñas "orejas" en la base, y en las puntas de las ramitas una yema grande marrón púrpura.'],
  look:['Tree 30 to 40 ft (9 to 12 m), often with several trunks. Huge leaves about 8 to 18 in (20 to 45 cm) clustered at branch tips like an umbrella, with two ear like lobes at the base. Large creamy white fragrant flowers; red, cone like fruit.',
        'Árbol de 9 a 12 m, a menudo con varios troncos. Hojas enormes de unos 20 a 45 cm agrupadas en las puntas como un paraguas, con dos lóbulos como orejas en la base. Flores grandes blanco crema y fragantes; fruto rojo parecido a un cono.'],
  life:['Flowers April and May; fruit ripens July and August and shows bright red seeds; leaves drop in fall.', 'Florece en abril y mayo; el fruto madura en julio y agosto y muestra semillas rojas; pierde las hojas en otoño.'],
  hab:['Rich coves and moist slopes. Deep, moist, well drained loam, slightly acidic.', 'Hondonadas fértiles y laderas húmedas. Suelo franco profundo, húmedo, bien drenado, ligeramente ácido.'],
  where:['NC Arboretum and Bent Creek, Craggy Gardens trails, Linville Falls, Moses Cone.', 'Arboreto y Bent Creek, senderos de Craggy Gardens, Linville Falls, Moses Cone.'],
  col:['Photo only on public land. With permission, a fallen leaf on private land.', 'Solo foto en tierra pública. Con permiso, una hoja caída en terreno privado.'] },

{ id:'rhododendron-calendulaceum', g:'dec', sci:'Rhododendron calendulaceum', fam:'Ericaceae', en:'Flame azalea', es:'Azalea llama', st:'N', nov:0, code:'B',
  el:[1000,6000,1], fl:[5,7], tb:'rhododendron-calendulaceum',
  now:['Bare twigs with old capsules and plump flower buds; hard to identify without help.', 'Ramitas desnudas con cápsulas viejas y yemas florales gruesas; difícil de identificar sin ayuda.'],
  look:['Deciduous shrub 5 to 12 ft (1.5 to 4 m). Hairy oval leaves clustered at branch tips. Funnel shaped flowers in orange, yellow or red with long curved stamens and little scent.', 'Arbusto caducifolio de 1,5 a 4 m. Hojas ovaladas y velludas agrupadas en las puntas. Flores en embudo naranja, amarillo o rojo, con estambres largos y curvos y poco aroma.'],
  life:['Blooms in May at low elevation and into early July on high balds; capsules September and October; red orange fall color.', 'Florece en mayo abajo y hasta principios de julio en las cumbres; cápsulas en septiembre y octubre; color rojo anaranjado en otoño.'],
  hab:['Open oak forests, forest edges and grassy balds. Acidic, well drained, humus rich soil.', 'Bosques abiertos de robles, bordes de bosque y cumbres de pasto. Suelo ácido, bien drenado y rico en humus.'],
  where:['Parkway edges near Craggy Gardens; NC Arboretum azalea collection. Off route: Roan Mountain balds, Black Balsam.', 'Bordes de la Parkway cerca de Craggy Gardens; colección de azaleas del Arboreto. Fuera de ruta: cumbres de Roan Mountain, Black Balsam.'],
  col:['Photo only in the wild. Native nurseries sell it.', 'Solo foto en estado silvestre. Se vende en viveros nativos.'],
  note:['Native azaleas were the passion of Chauncey Beadle, who managed the Biltmore nursery from 1890; his collection became the Azalea Garden at Biltmore in Asheville.', 'Las azaleas nativas fueron la pasión de Chauncey Beadle, quien dirigió el vivero de Biltmore desde 1890; su colección se convirtió en el Jardín de Azaleas de Biltmore en Asheville.'] },

/* ---------- Evergreen ground layer ---------- */
{ id:'galax-urceolata', g:'gro', sci:'Galax urceolata', fam:'Diapensiaceae', en:'Galax', es:'Galax', st:'N', nov:1, code:'P',
  law:['NC regulated harvest','Cosecha regulada en NC'], el:[1000,5000,1], fl:[5,7], tb:'galax-urceolata',
  now:['Leaves in sun turn bronze, red or maroon as cold triggers red pigments (anthocyanins); leaves in shade stay green. Dry flower wands with small capsules.', 'Las hojas al sol se tornan bronce, rojas o granate porque el frío activa pigmentos rojos (antocianinas); las de sombra siguen verdes. Varas florales secas con cápsulas pequeñas.'],
  look:['Rosettes of shiny, leathery, round to heart shaped leaves 2 to 5 in (5 to 13 cm) across, with small rounded teeth, on long stalks. Colonies often give off a musky, skunk like smell.', 'Rosetas de hojas brillantes, coriáceas, redondas a acorazonadas, de 5 a 13 cm, con dientes redondeados pequeños, sobre pecíolos largos. Las colonias suelen despedir un olor almizclado, como a zorrillo.'],
  life:['Perennial herb that spreads slowly by red orange rhizomes. Wands of tiny white flowers 8 to 15 in tall, May to July; capsules August to October. Harvested patches recover slowly.', 'Hierba perenne que se extiende lentamente por rizomas rojo anaranjados. Varas de florecitas blancas de 20 a 38 cm, de mayo a julio; cápsulas de agosto a octubre. Las manchas cosechadas se recuperan lentamente.'],
  hab:['Shady oak, rhododendron and laurel forests on slopes and ridges. Acidic, organic, well drained soils; a study of wild western North Carolina populations found soils near pH 4.2 to 4.5, with roots in decaying leaf litter.', 'Bosques sombreados de robles, rododendros y laureles en laderas y crestas. Suelos ácidos, orgánicos y bien drenados; un estudio en poblaciones silvestres del oeste de Carolina del Norte encontró pH cercano a 4,2 a 4,5, con raíces en la hojarasca.'],
  where:['Almost every forest trail: Rough Ridge, Linville Falls, Craggy Gardens, Moses Cone, Bent Creek.', 'Casi todos los senderos de bosque: Rough Ridge, Linville Falls, Craggy Gardens, Moses Cone, Bent Creek.'],
  col:['Photo only on public land. In North Carolina, taking galax from land you do not own requires the owner\'s written, dated permit (valid up to 180 days, naming the species). Take one or two leaves from a large colony; never pull rhizomes.', 'Solo foto en tierra pública. En Carolina del Norte, tomar galax de un terreno ajeno requiere permiso escrito y fechado del dueño (válido hasta 180 días, con la especie). Tomen una o dos hojas de una colonia grande; nunca arranquen rizomas.'],
  note:['The only species in its genus. Florists buy the leaves, and heavy harvest led to state and federal regulation.', 'Única especie de su género. Los floristas compran las hojas, y la cosecha intensa llevó a regulación estatal y federal.'] },

{ id:'gaultheria-procumbens', g:'gro', sci:'Gaultheria procumbens', fam:'Ericaceae', en:'Wintergreen, teaberry', es:'Gaulteria, té de monte', st:'C', nov:1, code:'B',
  el:[1000,6684,1], fl:[6,8], tb:'gaultheria-procumbens',
  now:['Bright red fruits about 0.4 in (1 cm) under the leaves last all winter. Leaves turn purple red in cold.', 'Frutos rojos brillantes de 1 cm bajo las hojas, duran todo el invierno. Las hojas se tornan rojo púrpura con el frío.'],
  look:['Tiny creeping shrub 4 to 8 in (10 to 20 cm). Glossy oval leaves 1 to 3 in (2.5 to 7.5 cm) clustered at the stem tip. Crush a leaf: it smells of wintergreen (methyl salicylate).', 'Arbusto rastrero diminuto de 10 a 20 cm. Hojas ovaladas brillantes de 2,5 a 7,5 cm agrupadas en la punta del tallo. Aplasten una hoja: huele a gaulteria (salicilato de metilo).'],
  life:['Spreads by underground stems. Waxy white bell flowers June to August; fruit from September through winter.', 'Se extiende por tallos subterráneos. Flores blancas cerosas en campana de junio a agosto; frutos de septiembre a todo el invierno.'],
  hab:['Dry acidic oak and pine woods, heath balds and rocky ridges, often under mountain laurel. Very acidic, sandy or rocky, well drained soils.', 'Bosques secos y ácidos de robles y pinos, brezales y crestas rocosas, a menudo bajo el laurel. Suelos muy ácidos, arenosos o rocosos, bien drenados.'],
  where:['Rough Ridge, Beacon Heights, Moses Cone carriage roads, Craggy Gardens.', 'Rough Ridge, Beacon Heights, caminos de Moses Cone, Craggy Gardens.'],
  col:['The fruit is edible, but leaf oil is toxic in large doses. Photo only on public land; garden centers sell it as a winter groundcover.', 'El fruto es comestible, pero el aceite de las hojas es tóxico en dosis altas. Solo foto en tierra pública; los centros de jardinería la venden.'] },

{ id:'mitchella-repens', g:'gro', sci:'Mitchella repens', fam:'Rubiaceae', en:'Partridgeberry', es:'Baya de perdiz', st:'C', nov:1, code:'P',
  el:[1000,4500,1], fl:[5,7], tb:'mitchella-repens',
  now:['Single red berries about 0.3 in (8 mm). Each forms from two fused flowers, so look for two small dimples on its tip.', 'Bayas rojas solitarias de unos 8 mm. Cada una nace de dos flores fusionadas: busquen dos hoyuelos en su punta.'],
  look:['Creeping plant 2 to 3 in (5 to 8 cm) tall forming mats. Paired, round, glossy leaves under 0.75 in (2 cm), each with a pale midvein.', 'Planta rastrera de 5 a 8 cm que forma tapetes. Hojas opuestas, redondas, brillantes, de menos de 2 cm, cada una con el nervio central pálido.'],
  life:['Roots along the stems. Fragrant white flowers in pairs, late spring and summer, in two forms with long or short styles, which favors cross pollination. Berries last through winter.', 'Enraíza a lo largo de los tallos. Flores blancas fragantes en pares, en primavera tardía y verano, de dos formas, con estilo largo o corto, lo que favorece la polinización cruzada. Las bayas duran el invierno.'],
  hab:['Moist, shady forests, stream banks and mossy logs. Acidic, humus rich soils.', 'Bosques húmedos y sombreados, orillas de arroyos y troncos con musgo. Suelos ácidos y ricos en humus.'],
  where:['Linville Falls, Price Lake, Moses Cone, NC Arboretum and Bent Creek.', 'Linville Falls, Price Lake, Moses Cone, Arboreto y Bent Creek.'],
  col:['Photo only on public land. With permission on private land.', 'Solo foto en tierra pública. Con permiso en terreno privado.'] },

{ id:'polystichum-acrostichoides', g:'gro', sci:'Polystichum acrostichoides', fam:'Dryopteridaceae', en:'Christmas fern', es:'Helecho de Navidad', st:'C', nov:1, code:'PB',
  el:[1000,5000,1], tb:'polystichum-acrostichoides',
  now:['Green fronds lie flat on the ground for winter. On fertile fronds the narrow upper third is brown, with spent spore cases underneath.', 'Las frondas verdes se recuestan en el suelo para el invierno. En las frondas fértiles, el tercio superior estrecho está marrón, con esporangios vacíos debajo.'],
  look:['Fern in a circular clump 1 to 3 ft (30 to 90 cm). Leathery fronds divided once. Each leaflet has a small "thumb" at its base, like a Christmas stocking. Round spore dots under the smaller leaflets at the frond tip.', 'Helecho en mata circular de 30 a 90 cm. Frondas coriáceas divididas una vez. Cada folíolo tiene un "pulgar" en la base, como una media de Navidad. Soros redondos bajo los folíolos más pequeños de la punta.'],
  life:['Perennial from a rhizome; no flowers or seeds. Spores, released in summer, grow into a tiny heart shaped gametophyte that produces a new fern. Silvery fiddleheads in April.', 'Perenne de rizoma; sin flores ni semillas. Las esporas, liberadas en verano, forman un gametófito diminuto en forma de corazón que produce un helecho nuevo. Cayados plateados en abril.'],
  hab:['Rich, rocky, shaded woods and stream banks. Moist, well drained, acidic to near neutral soils.', 'Bosques sombreados, rocosos y ricos, y orillas de arroyos. Suelos húmedos, bien drenados, ácidos a casi neutros.'],
  where:['Linville Falls, Price Lake, Moses Cone, NC Arboretum and Bent Creek.', 'Linville Falls, Price Lake, Moses Cone, Arboreto y Bent Creek.'],
  col:['Photo only on public land. With permission, one fertile leaflet is enough for spore microscopy. Nurseries sell it.', 'Solo foto en tierra pública. Con permiso, un folíolo fértil basta para microscopía de esporas. Se vende en viveros.'] },

{ id:'dryopteris-marginalis', g:'gro', sci:'Dryopteris marginalis', fam:'Dryopteridaceae', en:'Marginal wood fern', es:'Helecho de borde', st:'C', nov:1, code:'P',
  el:[1000,5000,1],
  now:['Evergreen, bluish green fronds stand out on rocky banks. Spent spore dots are still visible at the leaflet edges.', 'Frondas siempreverdes, verde azulado, destacan en taludes rocosos. Los soros vacíos aún se ven en el borde de los folíolos.'],
  look:['Vase shaped clump 1 to 2 ft (30 to 60 cm) from a scaly brown crown. Leathery, bluish green fronds cut into leaflets that are lobed again. Round spore dots sit right at the leaflet edges, which gives the name. Christmas fern is divided only once and has a "thumb" on each leaflet.', 'Mata en forma de jarrón de 30 a 60 cm, desde una corona marrón escamosa. Frondas coriáceas verde azulado, divididas en folíolos que a su vez se lobulan. Los soros redondos están justo en el borde de los folíolos, de ahí el nombre. El helecho de Navidad se divide solo una vez y tiene un "pulgar" en cada folíolo.'],
  life:['Perennial fern; spores in summer and fall. The crown does not spread, so each clump is one plant.', 'Helecho perenne; esporas en verano y otoño. La corona no se extiende, así que cada mata es una planta.'],
  hab:['Rocky wooded slopes, ledges and cliff bases. Moist, humus rich, acidic to near neutral, well drained soils.', 'Laderas boscosas rocosas, repisas y pies de riscos. Suelos húmedos, ricos en humus, ácidos a casi neutros, bien drenados.'],
  where:['Rocky trail cuts at Linville Falls, Moses Cone, lower Craggy Gardens trails, Bent Creek.', 'Taludes rocosos en Linville Falls, Moses Cone, senderos bajos de Craggy Gardens, Bent Creek.'],
  col:['Photo only on public land. With permission, one fertile leaflet on private land; never uproot the crown.', 'Solo foto en tierra pública. Con permiso, un folíolo fértil en terreno privado; nunca arranquen la corona.'] },

{ id:'polypodium-appalachianum', g:'gro', sci:'Polypodium appalachianum', fam:'Polypodiaceae', en:'Rock polypody', es:'Polipodio de roca', st:'N', nov:1, code:'P',
  el:[2500,6500],
  now:['Fully green and easy to spot on gray rock. Sori are ripe or spent, ideal for macro photography.', 'Totalmente verde y fácil de ver sobre la roca gris. Soros maduros o vacíos, ideales para macrofotografía.'],
  look:['Small evergreen fern 6 to 12 in (15 to 30 cm) in mats on boulders and cliffs. Leathery fronds cut almost to the midrib into smooth, round tipped lobes. Large round orange to brown spore dots in two rows, with no cover. Separating it from P. virginianum needs a hand lens and an expert.', 'Helecho siempreverde pequeño de 15 a 30 cm en tapetes sobre rocas y riscos. Frondas coriáceas cortadas casi hasta el eje en lóbulos lisos y redondeados. Soros grandes, redondos, naranja a marrón, en dos filas, sin cubierta. Separarlo de P. virginianum requiere lupa y un experto.'],
  life:['Perennial from a creeping rhizome on rock. P. virginianum is a fertile hybrid of this species and a northern one, P. sibiricum.', 'Perenne de rizoma rastrero sobre roca. P. virginianum es un híbrido fértil de esta especie y una norteña, P. sibiricum.'],
  hab:['Mossy boulders, cliff faces and rock walls, in a thin layer of humus. Acidic to neutral; middle to high elevations. Near endemic to the Appalachian chain.', 'Rocas musgosas, paredes de riscos y muros de piedra, en una capa delgada de humus. Ácido a neutro; altitudes medias y altas. Casi endémico de la cordillera de los Apalaches.'],
  where:['Boulders at Craggy Gardens, Rough Ridge, Beacon Heights, Linville Falls.', 'Rocas en Craggy Gardens, Rough Ridge, Beacon Heights, Linville Falls.'],
  col:['Photo only on public land. With permission, one frond, never the rhizome mat.', 'Solo foto en tierra pública. Con permiso, una fronda, nunca el tapete de rizomas.'] },

{ id:'diphasiastrum-digitatum', g:'gro', sci:'Diphasiastrum digitatum', fam:'Lycopodiaceae', en:'Fan clubmoss, running cedar', es:'Licopodio, pino rastrero', st:'C', nov:1, code:'P',
  el:[1000,5500,1],
  now:['Green fans with tan cones that have shed their yellow spores (July to October). Colonies form rings and lines across the forest floor.', 'Abanicos verdes con conos color canela que ya soltaron sus esporas amarillas (julio a octubre). Las colonias forman anillos y líneas en el suelo.'],
  look:['Not a moss: an ancient lineage of vascular plants. Upright shoots 3 to 8 in (8 to 20 cm) branched into flat fans like miniature cedar, rising from stems that run along the surface. Two to four spore cones on a long, forked stalk like a candelabra.', 'No es un musgo: un linaje antiguo de plantas vasculares. Brotes erguidos de 8 a 20 cm ramificados en abanicos planos como un cedro en miniatura, que salen de tallos que corren por la superficie. Dos a cuatro conos de esporas sobre un tallo largo y bifurcado, como un candelabro.'],
  life:['Spores grow into an underground, brown gametophyte that lives with soil fungi for years; a plant from spore can take about 20 years to mature.', 'Las esporas forman un gametófito marrón subterráneo que vive con hongos del suelo durante años; una planta de espora puede tardar unos 20 años en madurar.'],
  hab:['Open oak and pine woods, old fields and disturbed sites. Acidic, sandy or rocky, well drained soils.', 'Bosques abiertos de robles y pinos, campos viejos y sitios alterados. Suelos ácidos, arenosos o rocosos, bien drenados.'],
  where:['Moses Cone carriage roads, Price Park, NC Arboretum woods.', 'Caminos de Moses Cone, Price Park, bosques del Arboreto.'],
  col:['Once stripped for Christmas wreaths and nearly impossible to grow. Photo only on public land; with permission, one shoot from a large private colony.', 'Fue arrancado para coronas navideñas y casi no se puede cultivar. Solo foto en tierra pública; con permiso, un brote de una colonia privada grande.'] },

/* ---------- Wildflowers ---------- */
{ id:'actaea-racemosa', g:'wfl', sci:'Actaea racemosa', fam:'Ranunculaceae', en:'Black cohosh', es:'Cohosh negro', st:'C', nov:1, code:'P',
  el:[1000,5000,1], fl:[6,8], tb:'actaea-racemosa',
  now:['Dry, dark stalks lined with small oval pods. Shake them: the seeds rattle, hence the folk name "rattletop".', 'Tallos secos y oscuros con vainas ovaladas pequeñas. Agítenlos: las semillas suenan, de ahí el nombre popular "rattletop" (sonajero).'],
  look:['Tall herb 4 to 7 ft (1.2 to 2 m) with large leaves divided into toothed leaflets. Long white flower wands in summer, with no petals and an unpleasant smell.', 'Hierba alta de 1,2 a 2 m con hojas grandes divididas en folíolos dentados. Varas largas de flores blancas en verano, sin pétalos y de olor desagradable.'],
  life:['Perennial from a thick, knotty rhizome. Blooms May to August; pods July to September; the top dies back each winter.', 'Perenne de rizoma grueso y nudoso. Florece de mayo a agosto; vainas de julio a septiembre; la parte aérea muere cada invierno.'],
  hab:['Rich, moist cove forests and shady slopes. Deep, organic, moist soils, acidic to neutral.', 'Bosques de hondonada ricos y húmedos y laderas sombreadas. Suelos profundos, orgánicos y húmedos, ácidos a neutros.'],
  where:['NC Arboretum, Craggy Gardens Trail, rich slopes near Price Park.', 'Arboreto, sendero de Craggy Gardens, laderas ricas cerca de Price Park.'],
  col:['Never dig the root; wild harvest for herbal medicine is heavy. Photo only on public land; with permission, one dry stalk with pods.', 'Nunca extraigan la raíz; la cosecha silvestre para medicina herbal es intensa. Solo foto en tierra pública; con permiso, un tallo seco con vainas.'] },

{ id:'trillium-grandiflorum', g:'wfl', sci:'Trillium grandiflorum', fam:'Melanthiaceae', en:'Large flowered trillium', es:'Trilio de flor grande', st:'C', nov:0, code:'X',
  el:[1000,5000,1], fl:[4,5], tb:'trillium-grandiflorum',
  now:['Not visible: the plant dies back by late summer. Come back in April and May.', 'No visible: la planta desaparece a fines del verano. Vuelvan en abril y mayo.'],
  look:['Everything in threes: one whorl of three broad leaves, three green sepals, and one large white flower 2 to 4 in (5 to 10 cm) with three petals that turn pink with age.', 'Todo de a tres: un verticilo de tres hojas anchas, tres sépalos verdes y una gran flor blanca de 5 a 10 cm con tres pétalos que se vuelven rosados al envejecer.'],
  life:['Perennial from a rhizome; 7 to 10 years from seed to first flower. Flowers April and May; ants carry the seeds, attracted by a fatty appendage (elaiosome).', 'Perenne de rizoma; de 7 a 10 años desde la semilla hasta la primera flor. Florece en abril y mayo; las hormigas llevan las semillas, atraídas por un apéndice graso (eleosoma).'],
  hab:['Rich, moist deciduous cove forests. Deep, loamy, humus rich soil, slightly acidic to neutral.', 'Bosques caducifolios fértiles y húmedos. Suelo profundo, franco, rico en humus, ligeramente ácido a neutro.'],
  where:['In spring: NC Arboretum and Bent Creek, The Botanical Gardens at Asheville, Craggy Gardens area, Moses Cone.', 'En primavera: Arboreto y Bent Creek, Jardín Botánico de Asheville, zona de Craggy Gardens, Moses Cone.'],
  col:['Never pick: losing its leaves can kill the plant or stop it flowering for years. Trillium is listed in North Carolina\'s wild plant law (G.S. 14-129).', 'Nunca la corten: perder las hojas puede matarla o impedir que florezca por años. El trilio está en la ley de plantas silvestres de Carolina del Norte (G.S. 14-129).'] },

{ id:'sanguinaria-canadensis', g:'wfl', sci:'Sanguinaria canadensis', fam:'Papaveraceae', en:'Bloodroot', es:'Sanguinaria', st:'C', nov:0, code:'X',
  el:[1000,4000,1], fl:[3,4], tb:'sanguinaria-canadensis',
  now:['Not visible: leaves vanish by late summer.', 'No visible: las hojas desaparecen a fines del verano.'],
  look:['One rounded, deeply lobed blue green leaf wraps the flower stem. White flower 1.5 to 2 in (4 to 5 cm) with 8 to 12 petals, open only in sun for a day or two. The rhizome holds red orange sap.', 'Una hoja redonda, muy lobulada, verde azulada, envuelve el tallo floral. Flor blanca de 4 a 5 cm con 8 a 12 pétalos, abierta solo al sol uno o dos días. El rizoma tiene savia rojo anaranjada.'],
  life:['Perennial from a thick rhizome. Flowers March and April; ants spread the seeds.', 'Perenne de rizoma grueso. Florece en marzo y abril; las hormigas dispersan las semillas.'],
  hab:['Rich, moist deciduous forests and stream terraces at lower elevations. Loamy, humus rich, near neutral soil.', 'Bosques caducifolios fértiles y húmedos y terrazas de arroyos a baja altura. Suelo franco, rico en humus, casi neutro.'],
  where:['In spring: NC Arboretum (documented on its grounds), Bent Creek, The Botanical Gardens at Asheville.', 'En primavera: Arboreto (documentada en sus terrenos), Bent Creek, Jardín Botánico de Asheville.'],
  col:['Photo only; do not dig to see the sap. The sap is toxic and irritates skin. Listed in G.S. 14-129.', 'Solo foto; no la desentierren para ver la savia. La savia es tóxica e irrita la piel. Está en G.S. 14-129.'] },

{ id:'erythronium-americanum', g:'wfl', sci:'Erythronium americanum', fam:'Liliaceae', en:'Yellow trout lily', es:'Lirio trucha amarillo', st:'C', nov:0, code:'X',
  el:[1000,5000,1], fl:[3,5],
  now:['Not visible: a spring ephemeral that disappears by early summer.', 'No visible: una efímera de primavera que desaparece a principios del verano.'],
  look:['Pairs of leaves mottled brown and green like a trout\'s skin, at ground level. One nodding yellow lily flower on a 4 to 10 in (10 to 25 cm) stalk, petals swept back. Single leaves without a flower belong to plants not yet mature.', 'Pares de hojas moteadas de marrón y verde como la piel de una trucha, a ras del suelo. Una flor amarilla colgante, de pétalos recurvados, sobre un tallo de 10 a 25 cm. Las hojas solitarias sin flor son de plantas aún inmaduras.'],
  life:['Perennial from a deep corm; forms large colonies. Blooms March to May before the canopy leafs out; ants disperse the seeds.', 'Perenne de un cormo profundo; forma colonias grandes. Florece de marzo a mayo antes de que se cierre el dosel; las hormigas dispersan las semillas.'],
  hab:['Rich, moist deciduous forests and stream terraces. Loamy, humus rich, slightly acidic soil.', 'Bosques caducifolios fértiles y húmedos y terrazas de arroyos. Suelo franco, rico en humus, ligeramente ácido.'],
  where:['In spring: NC Arboretum and Bent Creek, cove forests along the Parkway.', 'En primavera: Arboreto y Bent Creek, bosques de hondonada en la Parkway.'],
  col:['Photo only; never dig the corm.', 'Solo foto; nunca desentierren el cormo.'] },

{ id:'lilium-superbum', g:'wfl', sci:'Lilium superbum', fam:'Liliaceae', en:'Turk\'s cap lily', es:'Lirio turbante', st:'C', nov:0, code:'X',
  el:[1000,5600,1], fl:[7,8], tb:'lilium-superbum',
  now:['Only dry capsules on dead stalks, if any.', 'Solo cápsulas secas en tallos muertos, si queda alguna.'],
  look:['Tall lily 3 to 8 ft (1 to 2.5 m), the largest native lily in the East. Smooth leaves in whorls. Many nodding orange flowers with purple brown spots, petals curled fully back like a turban, and a green star in the center.', 'Lirio alto de 1 a 2,5 m, el lirio nativo más grande del este. Hojas lisas en verticilos. Muchas flores naranjas colgantes con manchas púrpura, pétalos totalmente recurvados como un turbante y una estrella verde en el centro.'],
  life:['Perennial from a bulb. Flowers July and August; pollinated by swallowtail butterflies; capsules September and October.', 'Perenne de bulbo. Florece en julio y agosto; la polinizan mariposas cola de golondrina; cápsulas en septiembre y octubre.'],
  hab:['Moist meadows, forest edges, roadsides and coves. Moist, rich, acidic soil, sun to part shade.', 'Prados húmedos, bordes de bosque, cunetas y hondonadas. Suelo húmedo, fértil y ácido, sol a semisombra.'],
  where:['In summer: Parkway edges between Craggy Gardens and Mount Mitchell, Price Lake.', 'En verano: bordes de la Parkway entre Craggy Gardens y el Monte Mitchell, Price Lake.'],
  col:['Photo only.', 'Solo foto.'],
  note:['Look alike: Gray\'s lily (rare) has bell shaped flowers whose petals barely flare.', 'Parecido: el lirio de Gray (raro) tiene flores en campana cuyos pétalos apenas se abren.'] },

{ id:'monarda-didyma', g:'wfl', sci:'Monarda didyma', fam:'Lamiaceae', en:'Bee balm, Oswego tea', es:'Monarda, té de Oswego', st:'C', nov:0, code:'P',
  el:[2000,6000], fl:[7,8], tb:'monarda-didyma',
  now:['Dry, round seed heads on square stems; leaves may still smell of bergamot when crushed.', 'Cabezuelas secas y redondas en tallos cuadrados; las hojas aún pueden oler a bergamota al aplastarlas.'],
  look:['Mint family herb 2 to 4 ft (0.6 to 1.2 m). Square stem; opposite, toothed leaves that smell like Earl Grey tea. Round heads of bright scarlet tubular flowers, often with red bracts.', 'Hierba de la familia de la menta de 0,6 a 1,2 m. Tallo cuadrado; hojas opuestas y dentadas que huelen a té Earl Grey. Cabezuelas redondas de flores tubulares rojo escarlata, a menudo con brácteas rojas.'],
  life:['Perennial; spreads by runners. Flowers July and August; hummingbirds pollinate; seed heads September and October.', 'Perenne; se extiende por estolones. Florece en julio y agosto; la polinizan colibríes; cabezuelas secas en septiembre y octubre.'],
  hab:['Moist forest openings, stream banks and seeps. Moist, rich, slightly acidic soil.', 'Claros húmedos, orillas de arroyos y rezumaderos. Suelo húmedo, fértil, ligeramente ácido.'],
  where:['In summer: Craggy Gardens, Mount Mitchell road edges. Off route: Graveyard Fields, Elk Knob.', 'En verano: Craggy Gardens, bordes del camino al Monte Mitchell. Fuera de ruta: Graveyard Fields, Elk Knob.'],
  col:['Photo only on public land. Nurseries sell it.', 'Solo foto en tierra pública. Se vende en viveros.'] },

/* ---------- Mosses and lichens ---------- */
{ id:'polytrichum-commune', g:'mos', sci:'Polytrichum commune', fam:'Polytrichaceae', en:'Common haircap moss', es:'Musgo pelo de oro', st:'C', nov:1, code:'P',
  now:['Deep green carpets. Dry leaves fold tight against the stem; wet them and they open within a minute.', 'Alfombras verde oscuro. Secas, las hojas se pliegan contra el tallo; al mojarlas se abren en menos de un minuto.'],
  look:['One of the tallest mosses, 2 to 16 in (5 to 40 cm), with stiff stems and narrow leaves spreading like small stars. Spore capsules on wiry stalks wear a hairy hood, hence "haircap".', 'Uno de los musgos más altos, de 5 a 40 cm, con tallos rígidos y hojas estrechas abiertas como estrellitas. Las cápsulas, sobre tallos finos, llevan una caperuza peluda.'],
  life:['Separate male and female plants. Males carry cup shaped heads that splash sperm to females in rain; the fertilized female grows a capsule that releases spores in summer and fall.', 'Plantas masculinas y femeninas separadas. Los machos tienen cabezas en copa que salpican esperma a las hembras con la lluvia; la hembra fecundada produce una cápsula que suelta esporas en verano y otoño.'],
  hab:['Wet, acidic, open ground: seeps, bog edges, trail sides, old fields. All elevations. Under the microscope, leaves carry rows of thin green ridges (lamellae).', 'Suelos húmedos, ácidos y abiertos: rezumaderos, bordes de turberas, orillas de senderos, campos viejos. Todas las altitudes. Al microscopio, las hojas llevan filas de crestas verdes delgadas (lamelas).'],
  where:['Price Lake edges, Moses Cone, Craggy Gardens, Mount Mitchell.', 'Orillas de Price Lake, Moses Cone, Craggy Gardens, Monte Mitchell.'],
  col:['Photo only on public land. With permission, a few stems from a large carpet.', 'Solo foto en tierra pública. Con permiso, unos tallos de una alfombra grande.'] },

{ id:'sphagnum', g:'mos', sci:'Sphagnum', fam:'Sphagnaceae', en:'Peat moss', es:'Esfagno, musgo de turbera', st:'C', nov:1, code:'B', wk:'Sphagnum', inat:'Sphagnum',
  now:['Red and gold tones deepen in cold; carpets are soaked and easy to see.', 'Los tonos rojos y dorados se intensifican con el frío; las alfombras están empapadas y fáciles de ver.'],
  look:['Soft, spongy cushions in green, gold or red. Each stem ends in a dense head like a tiny pom pom. Squeeze it: water pours out.', 'Cojines blandos y esponjosos verdes, dorados o rojos. Cada tallo termina en una cabeza densa como un pompón diminuto. Apriétenlo: sale mucha agua.'],
  life:['Grows at the top while lower parts die and slowly turn into peat over centuries. Round black capsules burst in summer and shoot out spores.', 'Crece por arriba mientras las partes bajas mueren y se convierten lentamente en turba durante siglos. Cápsulas negras redondas estallan en verano y lanzan las esporas.'],
  hab:['Seeps, bogs and wet spots; very acidic, nutrient poor, waterlogged ground that the moss makes even more acidic. Leaves are a net of narrow living cells around large empty cells with pores that store water.', 'Rezumaderos, turberas y sitios encharcados; suelo muy ácido, pobre y saturado que el musgo acidifica aún más. Las hojas son una red de células vivas estrechas alrededor de células grandes vacías con poros que almacenan agua.'],
  where:['Seeps along Boone Fork and Price Lake, wet spots on Mount Mitchell.', 'Rezumaderos en Boone Fork y Price Lake, sitios húmedos del Monte Mitchell.'],
  col:['Photo only in the wild: mountain bogs shelter rare species. Garden centers sell dried sphagnum, often harvested in Chile (Sphagnum magellanicum).', 'Solo foto en estado silvestre: las turberas de montaña albergan especies raras. Los centros de jardinería venden esfagno seco, a menudo cosechado en Chile (Sphagnum magellanicum).'] },

{ id:'usnea', g:'mos', sci:'Usnea', fam:'Parmeliaceae', en:'Old man\'s beard lichen', es:'Barba de viejo, barba de piedra', st:'C', nov:1, code:'P', wk:'Usnea', inat:'Usnea',
  now:['Soft, bright and swollen in fog. Wind throws many lichen covered twigs to the ground.', 'Suave, brillante e hinchada con la niebla. El viento tumba muchas ramitas con liquen.'],
  look:['A lichen: a fungus living with algae. Pale gray green tufts or hanging strands on twigs. Test: gently stretch a wet strand; the outer layer cracks and shows a white, elastic inner cord. Only Usnea has this cord.', 'Un liquen: un hongo que vive con algas. Mechones o hebras verde grisáceo pálido en las ramitas. Prueba: estiren con cuidado una hebra mojada; la capa externa se agrieta y muestra un cordón interno blanco y elástico. Solo Usnea lo tiene.'],
  life:['Grows a few millimeters a year; spreads mostly by fragments and powdery packets holding both fungus and alga.', 'Crece unos milímetros al año; se dispersa sobre todo por fragmentos y paquetes polvorientos con hongo y alga juntos.'],
  hab:['Branches of spruce, fir, birch and oak in foggy, humid forests. Sensitive to air pollution, so it signals clean air. Most abundant at high elevation.', 'Ramas de pícea, abeto, abedul y roble en bosques nublados y húmedos. Sensible a la contaminación, indica aire limpio. Más abundante en altura.'],
  where:['Mount Mitchell, Craggy Gardens, Grandfather Mountain, old trees at Moses Cone.', 'Monte Mitchell, Craggy Gardens, Grandfather Mountain, árboles viejos de Moses Cone.'],
  col:['Photo only on public land, fallen twigs included. With permission, fallen lichen covered twigs on private land are the gentlest sample of all.', 'Solo foto en tierra pública, incluidas ramitas caídas. Con permiso, las ramitas caídas con liquen en terreno privado son la muestra más suave.'] },

{ id:'cladonia', g:'mos', sci:'Cladonia', fam:'Cladoniaceae', en:'Reindeer lichens and British soldiers', es:'Líquenes de reno y soldaditos', st:'C', nov:1, code:'X', wk:'Cladonia rangiferina', inat:'Cladonia',
  now:['Soft and spongy after rain, crisp and brittle when dry. The red caps of British soldiers are fungal fruiting bodies that make spores.', 'Blandos tras la lluvia, crujientes y frágiles en seco. Las puntas rojas de los soldaditos son cuerpos fructíferos del hongo que producen esporas.'],
  look:['Reindeer lichens (C. rangiferina and relatives): pale gray, densely branched cushions 2 to 4 in (5 to 10 cm), like tiny coral. British soldiers (C. cristatella): small gray green stalks under 1 in (2.5 cm) with bright red caps.', 'Líquenes de reno (C. rangiferina y afines): cojines gris pálido muy ramificados de 5 a 10 cm, como coral diminuto. Soldaditos (C. cristatella): tallitos verde grisáceo de menos de 2,5 cm con puntas rojo brillante.'],
  life:['Very slow: a few millimeters a year. A footprint on a dry mat can erase decades of growth.', 'Muy lentos: unos milímetros al año. Una pisada sobre un tapete seco puede borrar décadas de crecimiento.'],
  hab:['Sunny rock outcrops, thin soil over granite and gneiss, heath balds, old logs. Acidic, dry, nutrient poor ground.', 'Afloramientos soleados, suelo delgado sobre granito y gneis, brezales, troncos viejos. Suelos ácidos, secos y pobres.'],
  where:['Rough Ridge boardwalk, Beacon Heights, Craggy Pinnacle summit.', 'Pasarela de Rough Ridge, Beacon Heights, cumbre de Craggy Pinnacle.'],
  col:['Photo only, from the trail or boardwalk. Craft stores sell dyed "reindeer moss", useful for practice but chemically treated.', 'Solo foto, desde el sendero o la pasarela. Las tiendas de manualidades venden "musgo de reno" teñido, útil para practicar pero tratado químicamente.'] },

{ id:'umbilicaria-mammulata', g:'mos', sci:'Umbilicaria mammulata', fam:'Umbilicariaceae', en:'Smooth rock tripe', es:'Tripa de roca', st:'C', nov:1, code:'X',
  now:['After rain the plates turn green and flexible; dry, they turn brown, curl and become brittle.', 'Después de la lluvia las placas se ponen verdes y flexibles; secas, se vuelven marrones, se enroscan y se quiebran.'],
  look:['Large, round, leathery brown plates on vertical rock, from palm size to more than 1 ft (30 cm), among the largest lichens in North America. Black and velvety below. Each plate is attached at one central point, like a navel (umbilicus).', 'Placas grandes, redondas y coriáceas sobre roca vertical, del tamaño de una mano a más de 30 cm, entre los líquenes más grandes de Norteamérica. Negras y aterciopeladas por debajo. Cada placa se fija en un solo punto central, como un ombligo.'],
  life:['Extremely slow growing; large plates may be many decades old.', 'Crecimiento extremadamente lento; las placas grandes pueden tener muchas décadas.'],
  hab:['Shaded or north facing cliffs and boulders of acidic rock such as granite and gneiss, often near streams.', 'Riscos y rocas sombreadas u orientadas al norte, de roca ácida como granito y gneis, a menudo cerca de arroyos.'],
  where:['Boulders and rock faces at Linville Falls, Rough Ridge, Beacon Heights, Craggy Gardens.', 'Rocas y paredes en Linville Falls, Rough Ridge, Beacon Heights, Craggy Gardens.'],
  col:['Photo only. Removing a plate destroys decades of growth.', 'Solo foto. Retirar una placa destruye décadas de crecimiento.'] },

/* ---------- Rare: observe only ---------- */
{ id:'geum-radiatum', g:'rar', sci:'Geum radiatum', fam:'Rosaceae', en:'Spreading avens', es:'Geum de cumbre', st:'R', nov:1, code:'X',
  law:['Federally endangered','En peligro (federal)'], el:[4370,6684], fl:[6,9], fws:'https://fws.gov/species/spreading-avens-geum-radiatum',
  now:['Rosettes of large, kidney shaped leaves on cliff ledges, if you can see them from the trail.', 'Rosetas de hojas grandes en forma de riñón en repisas de riscos, si se ven desde el sendero.'],
  look:['Basal leaves with one large, round, toothed end lobe; bright yellow five petaled flowers about 1 in (2.5 cm) on stems 8 to 20 in.', 'Hojas basales con un lóbulo final grande, redondo y dentado; flores amarillas de cinco pétalos de unos 2,5 cm sobre tallos de 20 a 50 cm.'],
  hab:['Steep, sunny cliffs and ledges with gravelly, acidic soil on a few peaks above about 4,370 ft (1,310 m) on the North Carolina and Tennessee border, near red spruce.', 'Riscos empinados y soleados con suelo ácido y pedregoso en pocas cumbres sobre unos 1.310 m en la frontera de Carolina del Norte y Tennessee, cerca de píceas.'],
  where:['Grandfather Mountain and Roan Mountain, among a few others. Locations are given at mountain level on purpose.', 'Grandfather Mountain y Roan Mountain, entre pocas otras. Las ubicaciones se dan a nivel de montaña a propósito.'] },

{ id:'solidago-spithamaea', g:'rar', sci:'Solidago spithamaea', fam:'Asteraceae', en:'Blue Ridge goldenrod', es:'Vara de oro de Blue Ridge', st:'R', nov:0, code:'X',
  law:['Federally threatened','Amenazada (federal)'], el:[4600,6000], fl:[7,9], fws:'https://www.fws.gov/species/blue-ridge-goldenrod-solidago-spithamaea',
  now:['Only small basal leaves and dry flower heads; not identifiable from a distance.', 'Solo hojas basales pequeñas y cabezuelas secas; no se identifica a distancia.'],
  look:['Dwarf goldenrod only 4 to 8 in (10 to 20 cm) tall; the name means "one span tall". Smooth foliage, toothed stem leaves that do not clasp the stem, and flat topped clusters of golden flowers. Goldenrods are hard to identify; a small yellow plant on a summit is not enough evidence.', 'Vara de oro enana de solo 10 a 20 cm; el nombre significa "de un palmo de alto". Follaje liso, hojas del tallo dentadas que no lo abrazan y grupos planos de flores doradas. Las varas de oro son difíciles: una planta amarilla pequeña en una cumbre no basta.'],
  hab:['Cracks in sunny rock outcrops, cliffs and ledges, generally above 4,600 ft (1,400 m), in thin, acidic soil. A cold climate relict that survived on cool summits.', 'Grietas de afloramientos soleados, riscos y repisas, en general sobre 1.400 m, en suelo delgado y ácido. Un relicto de clima frío que sobrevivió en cumbres frescas.'],
  where:['Grandfather Mountain, Hanging Rock (Avery County) and Roan Mountain areas only. Stay on the trail.', 'Solo en las zonas de Grandfather Mountain, Hanging Rock (condado de Avery) y Roan Mountain. No salgan del sendero.'] },

{ id:'liatris-helleri', g:'rar', sci:'Liatris helleri', fam:'Asteraceae', en:'Heller\'s blazing star', es:'Liatris de Heller', st:'R', nov:0, code:'X',
  law:['Federally threatened','Amenazada (federal)'], el:[3500,6000], fl:[7,9], fws:'https://www.fws.gov/species/hellers-blazing-star-liatris-helleri',
  now:['Dry stems with fluffy seed heads at most.', 'Como mucho, tallos secos con cabezuelas plumosas.'],
  look:['Narrow, pale green leaves near the base; stems to about 16 in (40 cm) ending in a dense spike of lavender flower heads that open from the top down. The genus is difficult and hybridizes, so a photo may not confirm the species.', 'Hojas estrechas verde pálido cerca de la base; tallos de unos 40 cm que terminan en una espiga densa de cabezuelas lavanda que abren de arriba hacia abajo. El género es difícil e hibrida; una foto puede no confirmar la especie.'],
  hab:['Sparsely vegetated outcrops, cliffs and ledges at about 3,500 to 6,000 ft (1,070 to 1,830 m), on shallow acidic soil over igneous or metamorphic rock.', 'Afloramientos, riscos y repisas con poca vegetación, a unos 1.070 a 1.830 m, en suelo ácido y poco profundo sobre roca ígnea o metamórfica.'],
  where:['Endemic to Avery, Ashe, Burke, Caldwell and Watauga counties, including the Grandfather Mountain area. Trampling and poaching are documented threats.', 'Endémica de los condados de Avery, Ashe, Burke, Caldwell y Watauga, incluida la zona de Grandfather Mountain. El pisoteo y la extracción ilegal son amenazas documentadas.'] },

{ id:'houstonia-montana', g:'rar', sci:'Houstonia montana', fam:'Rubiaceae', en:'Roan Mountain bluet', es:'Azulita de Roan', st:'R', nov:0, code:'X',
  law:['Federally endangered','En peligro (federal)'], fl:[5,8], fws:'https://www.fws.gov/species/roan-mountain-bluet-hedyotis-purpurea-var-montana',
  now:['Small leaf rosettes, very hard to see.', 'Rosetas pequeñas, muy difíciles de ver.'],
  look:['Tufts 4 to 6 in (10 to 15 cm) with small oval leaves in pairs and clusters of four lobed, deep reddish purple flowers, darker and larger than common bluets. Also called Hedyotis purpurea var. montana.', 'Matas de 10 a 15 cm con hojitas ovaladas en pares y grupos de flores de cuatro lóbulos, púrpura rojizo intenso, más oscuras y grandes que las azulitas comunes. También llamada Hedyotis purpurea var. montana.'],
  hab:['Rock crevices, outcrops and grassy slopes on the highest peaks, in thin soil and full sun. Two flower forms that must cross; pollinated by syrphid flies and bumblebees.', 'Grietas, afloramientos y laderas de pasto en las cumbres más altas, en suelo delgado y a pleno sol. Dos formas florales que deben cruzarse; la polinizan sírfidos y abejorros.'],
  where:['Roan Mountain and Grandfather Mountain.', 'Roan Mountain y Grandfather Mountain.'] },

{ id:'hudsonia-montana', g:'rar', sci:'Hudsonia montana', fam:'Cistaceae', en:'Mountain golden heather', es:'Hudsonia de montaña', st:'R', nov:1, code:'X',
  law:['Federally threatened','Amenazada (federal)'], el:[2800,3850], fl:[5,6], fws:'https://www.fws.gov/apps/carp/species/mountain-golden-heather-hudsonia-montana',
  now:['Low mats of needle like green leaves, visible all year.', 'Matas bajas de hojas verdes como agujas, visibles todo el año.'],
  look:['Tiny woody shrub 3 to 6 in (8 to 15 cm) high, like a cushion of moss or a low juniper. Yellow flowers, each open a single day, late May and June.', 'Arbusto leñoso diminuto de 8 a 15 cm, como un cojín de musgo o un enebro rastrero. Flores amarillas que duran un solo día, a fines de mayo y en junio.'],
  hab:['Sunny ledges of Chilhowee quartzite with shallow, sandy, gravelly soil, at about 2,800 to 3,850 ft. Needs open conditions; fire suppression and trampling are threats.', 'Repisas soleadas de cuarcita Chilhowee con suelo arenoso y pedregoso poco profundo, a unos 850 a 1.175 m. Necesita condiciones abiertas; la supresión del fuego y el pisoteo la amenazan.'],
  where:['Only in the Linville Mountains, Burke and McDowell counties, on Pisgah National Forest land. Off your main route; ask the Forest Service about guided interpretation.', 'Solo en las montañas de Linville, condados de Burke y McDowell, en el Bosque Nacional Pisgah. Fuera de su ruta; pregunten al Servicio Forestal por visitas guiadas.'] },

{ id:'gymnoderma-lineare', g:'rar', sci:'Gymnoderma lineare', fam:'Cladoniaceae', en:'Rock gnome lichen', es:'Liquen gnomo de roca', st:'R', nov:1, code:'X',
  law:['Federally endangered','En peligro (federal)'], el:[4900,6684],
  now:['Visible all year on shaded summit cliffs.', 'Visible todo el año en riscos sombreados de las cumbres.'],
  look:['Clumps of tiny strap shaped, gray green lobes 0.2 to 1 in (5 to 25 mm) long, whitish below and black toward the base.', 'Grupos de lóbulos diminutos en forma de cinta, verde grisáceo, de 5 a 25 mm, blanquecinos por debajo y negros hacia la base.'],
  hab:['Vertical, shaded rock faces in frequent fog, mostly above 4,900 ft (1,500 m), and in deep river gorges. Southern Appalachian endemic.', 'Paredes verticales sombreadas con niebla frecuente, sobre todo por encima de 1.500 m, y gargantas profundas. Endémico del sur de los Apalaches.'],
  where:['High peaks of the region. Never touch lichens on shaded summit cliffs.', 'Cumbres altas de la región. Nunca toquen líquenes en riscos sombreados de las cumbres.'] },

{ id:'lilium-grayi', g:'rar', sci:'Lilium grayi', fam:'Liliaceae', en:'Gray\'s lily', es:'Lirio de Gray', st:'R', nov:0, code:'X',
  law:['NC threatened; federal species of concern','Amenazada en NC; especie de interés federal'], fl:[6,7],
  now:['Dormant underground.', 'En reposo bajo tierra.'],
  look:['Lily 2 to 5 ft (0.6 to 1.5 m) with whorled leaves and nodding, bell shaped flowers, deep crimson outside, orange yellow and purple spotted inside; petals barely flare, unlike Turk\'s cap lily.', 'Lirio de 0,6 a 1,5 m con hojas en verticilos y flores colgantes en campana, carmesí por fuera, amarillo anaranjado con manchas púrpura por dentro; los pétalos apenas se abren, a diferencia del lirio turbante.'],
  hab:['Wet meadows, seeps, bog edges and grassy balds at middle to high elevation. Pollinated by hummingbirds. Threatened by the fungal blight Botrytis elliptica, trampling and shrubs closing the balds.', 'Prados húmedos, rezumaderos, bordes de turberas y cumbres de pasto a altitud media y alta. La polinizan colibríes. La amenazan el hongo Botrytis elliptica, el pisoteo y los arbustos que cierran las cumbres.'],
  where:['Roan Mountain balds and a few seeps near the Parkway; blooms June and July.', 'Cumbres de Roan Mountain y algunos rezumaderos cerca de la Parkway; florece en junio y julio.'] },

{ id:'rhododendron-vaseyi', g:'rar', sci:'Rhododendron vaseyi', fam:'Ericaceae', en:'Pinkshell azalea', es:'Azalea concha rosada', st:'R', nov:0, code:'X',
  law:['Endemic to North Carolina','Endémica de Carolina del Norte'], fl:[5,6],
  now:['Bare deciduous shrub with plump flower buds.', 'Arbusto caducifolio desnudo con yemas florales gruesas.'],
  look:['Deciduous shrub with pale pink, open flowers in spring before the leaves.', 'Arbusto caducifolio con flores abiertas rosa pálido en primavera, antes de las hojas.'],
  hab:['Bogs, seeps, spruce forest edges and heath balds in a few North Carolina mountain counties.', 'Turberas, rezumaderos, bordes del bosque de píceas y brezales en pocos condados de montaña de Carolina del Norte.'],
  where:['Grandfather Mountain is a stronghold.', 'Grandfather Mountain es un baluarte.'] },

{ id:'trillium-vaseyi', g:'rar', sci:'Trillium vaseyi', fam:'Melanthiaceae', en:'Vasey\'s trillium', es:'Trilio de Vasey', st:'R', nov:0, code:'X',
  law:['Rare regional endemic','Endémica regional rara'], fl:[4,5],
  now:['Not visible.', 'No visible.'],
  look:['One of the largest trilliums, to about 2 ft (60 cm), with three broad leaves. A deep maroon, fragrant flower nods below the leaves.', 'Uno de los trilios más grandes, de hasta 60 cm, con tres hojas anchas. Una flor granate oscuro y fragante cuelga bajo las hojas.'],
  hab:['Deep shade of rich, undisturbed cove forests with moist, humus rich soils. Slow: many years from seed to flower; ants disperse the seeds.', 'Sombra profunda de bosques de hondonada ricos y sin perturbar, con suelos húmedos y ricos en humus. Lento: muchos años de semilla a flor; las hormigas dispersan las semillas.'],
  where:['Southern Blue Ridge Escarpment, southwest of Asheville; off your route.', 'Escarpe sur de la Blue Ridge, al suroeste de Asheville; fuera de su ruta.'] },

{ id:'shortia-galacifolia', g:'rar', sci:'Shortia galacifolia', fam:'Diapensiaceae', en:'Oconee bells', es:'Campanas de Oconee', st:'R', nov:1, code:'X',
  law:['Globally rare','Rara a nivel mundial'], fl:[3,4],
  now:['Evergreen leaves, like small galax with scalloped edges.', 'Hojas siempreverdes, como galax pequeña de borde festoneado.'],
  look:['Glossy, rounded, scalloped evergreen leaves smaller than galax; nodding white to pale pink bells with fringed petals in March and April. Galax\'s closest relative.', 'Hojas siempreverdes brillantes, redondeadas y festoneadas, más pequeñas que las de galax; campanas colgantes blancas a rosa pálido con pétalos flecados en marzo y abril. El pariente más cercano de galax.'],
  hab:['Shaded stream banks and moist ravines, very sensitive to trampling and changes in water flow.', 'Orillas sombreadas de arroyos y barrancos húmedos, muy sensible al pisoteo y a cambios en el agua.'],
  where:['A few counties where North Carolina, South Carolina and Georgia meet; off your route.', 'Pocos condados donde se juntan Carolina del Norte, Carolina del Sur y Georgia; fuera de su ruta.'] },

{ id:'panax-quinquefolius', g:'rar', sci:'Panax quinquefolius', fam:'Araliaceae', en:'American ginseng', es:'Ginseng americano', st:'R', nov:0, code:'X',
  law:['Collection prohibited on national forests in NC; CITES listed','Prohibida en bosques nacionales de NC; en CITES'], fl:[6,7],
  now:['Yellow leaves have fallen. Do not search for it or disturb it.', 'Las hojas amarillas ya cayeron. No lo busquen ni lo perturben.'],
  look:['Herb with whorls of five part leaves and a cluster of red berries in late summer.', 'Hierba con verticilos de hojas de cinco folíolos y un racimo de bayas rojas a fines del verano.'],
  hab:['Rich, shady cove forests.', 'Bosques de hondonada ricos y sombreados.'],
  where:['Not a visit target. Its root is poached for export.', 'No es un objetivo de visita. Su raíz se extrae ilegalmente para exportación.'] }
];

